                                                                                                                                                                                                 
  CREATE TABLE "DICTIONARY_MAP"                                                                                                                                                       
   (	"ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 23 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"VALUE" NVARCHAR2(128) NOT NULL ENABLE,                                                                                                                                                         
	"KEY" VARCHAR2(64) NOT NULL ENABLE,                                                                                                                                                             
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                             
	"TYPE" NVARCHAR2(32),                                                                                                                                                                           
	"UPDATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                      
	"UPDATE_DATE" DATE NOT NULL ENABLE,                                                                                                                                                             
	"REMARK" NVARCHAR2(512),                                                                                                                                                                        
	"CREATED_BY" NUMBER(20,0) DEFAULT null NOT NULL ENABLE,                                                                                                                                         
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                           
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                   
	 PRIMARY KEY ("ID")                                                                                                                                                                             
  USING INDEX  ENABLE                                                                                                                                                                            
   ) ;                                                                                                                                                                                           

